<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Holder\TrustedClientAllowedRedirectsVersionAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedRedirectsVersionAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TrustedClientAllowedRedirectsVersionAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getVersion returns null on a freshly created holder.
     */
    public function testVersionNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedRedirectsVersionAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isVersionAssigned());
        $this->assertNull($holder->getVersion());
    }
}
class ImplWithTrustedClientAllowedRedirectsVersionAttributeHolderUnitTest
{
    use TrustedClientAllowedRedirectsVersionAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedVersionRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultVersion();
    }
}
